    TwistSquash::SquashKeyA(PROCYON_KEY_A_D_IceLaneA, PROCYON_KEY_A_D_IceLaneB, PROCYON_KEY_A_D_IceLaneC, PROCYON_KEY_A_D_IceLaneD, &(pWorkSpace->mKeyBoxA[3U][0]));

